# ROLES — the 29 staffing/JD cards (+3 execs +2 contractors). Compensation is NOT here (overlay). kpi ids → bm_kpis.ROLE_KPIS
def R(code, title, fn, manager, reports, count, filled, priority, fix, purpose, decides, escalates, inputs, outputs, deps, nature, conf="CONFIRMED", src=("S01", "S02"), note=None):
    # `fix` is accepted for authoring compatibility but NEVER stored: compensation lives in overlay/ov_compensation.py (CONFIDENTIAL)
    d = {"code": code, "title": title, "function": fn, "manager": manager, "reports": reports, "positions": count, "filled": filled, "vacancy_priority": priority,
         "compensation": "OVERLAY", "purpose": purpose, "decision_rights": decides, "escalation_path": escalates, "inputs": inputs, "outputs": outputs,
         "dependencies": deps, "work_nature": nature, "kpis": f"ROLE_KPIS[{code!r}]", "src": list(src), "conf": conf}
    if note: d["note"] = note
    return d

